  "devdoc": {
    "details": "Contract deployed on BaseSep that maintains ENS records",
    "kind": "dev",
    "methods": {
      "authorizeCaller(address,bool)": {
        "details": "Authorize a caller (resolver, registrar, Lit key, etc.) to modify records"
      },
      "batchSetRecords(bytes32[],address[],string[][],string[][])": {
        "details": "Batch set multiple records for efficiency"
      },
      "exportState(bytes32[],string[])": {
        "details": "Export the complete state for a batch of nodes",
        "params": {
          "commonKeys": "Array of text record keys to export for all nodes",
          "nodes": "Array of node hashes to export"
        },
        "returns": {
          "nodeData": "Array of structs containing all data for each node"
        }
      },
      "getAddress(bytes32)": {
        "details": "Get address record (called by CCIP-Read via RPC) This is the function the DirectRPCResolver will call"
      },
      "getRecords(bytes32,string[])": {
        "details": "Get multiple records in one call (for efficiency)"
      },
      "getText(bytes32,string)": {
        "details": "Get text record (called by CCIP-Read via RPC) This is the function the DirectRPCResolver will call"
      },
      "getTextRecordKeys(bytes32,string[])": {
        "details": "Get all text record keys for a node (up to a limit) Note: This is not gas-efficient and should only be used for queries"
      },
      "hasRecords(bytes32)": {
        "details": "Check if a node has any records set"
      },
      "owner()": {
        "details": "Returns the address of the current owner."
      },
      "renounceOwnership()": {
        "details": "Leaves the contract without owner. It will not be possible to call `onlyOwner` functions. Can only be called by the current owner. NOTE: Renouncing ownership will leave the contract without an owner, thereby disabling any functionality that is only available to the owner."
      },
      "setAddress(bytes32,address)": {
        "details": "Set address record for a node"
      },
      "setProtocolAddress(address)": {
        "details": "Set the protocol address that can authorize Lit keys"
      },
      "setText(bytes32,string,string)": {
        "details": "Set text record for a node"
      },
      "transferOwnership(address)": {
        "details": "Transfers ownership of the contract to a new account (`newOwner`). Can only be called by the current owner."
      }
    },
    "title": "ENSSubdomainRecordsContract",
    "version": 1
  },
